-- Import: makes the Excel price lists the source of truth for Stonewater and
-- Kasper products (124 products, live on rgapricelist.netlify.app as of
-- 2026-10-05; only the typed-in Excel columns are stored, derived prices come
-- from price_catalog). Run after 001_price_tables.sql. Safe to re-run.
--
--   * A product that already exists (same brand + model number, ignoring case
--     and extra spaces) is updated IN PLACE: same id, so its SKUs/barcodes and
--     image stay attached. Name, model, description, price-list group, order,
--     status and prices come from Excel; its product type is kept.
--   * Any other product is inserted with the type listed per row ("type").
--   * Slugs are regenerated as <brand slug>-<model>.
--   * CS-4LM is discontinued; D1000 (not in Excel, no SKUs) is deleted.
--   * Brand "Stonewater Audio" is renamed "Stonewater" (slug unchanged).
--   * No category or barcode prefix is created, changed or deleted.

begin;

update public.brands set name = 'Stonewater' where slug = 'stonewater-audio';

do $import$
declare
  x jsonb; v_id uuid; v_type uuid; n_upd int := 0; n_new int := 0;
  norm constant text := '\s+';
begin
  if not exists (select 1 from public.brands where slug = 'stonewater-audio')
     or not exists (select 1 from public.brands where slug = 'kasper') then
    raise exception 'Brands stonewater-audio and kasper must exist';
  end if;

