]$json$::jsonb) loop
    select p.id into v_id
    from public.products p join public.brands b on b.id = p.brand_id
    where b.slug = x->>'brand'
      and lower(regexp_replace(btrim(p.model_number), norm, ' ', 'g'))
        = lower(regexp_replace(btrim(x->>'model'), norm, ' ', 'g'));

    if v_id is null then
      select id into v_type from public.categories where slug = x->>'type';
      if v_type is null then raise exception 'Unknown product type "%" for %', x->>'type', x->>'model'; end if;
      perform public.price_save_product((x - 'type') || jsonb_build_object('type_id', v_type));
      n_new := n_new + 1;
    else
      perform public.price_save_product((x - 'type') || jsonb_build_object('id', v_id));
      n_upd := n_upd + 1;
    end if;
  end loop;

  raise notice 'price import: % updated, % inserted', n_upd, n_new;
end
$import$;

-- Regenerate slugs for every product the import touched.
update public.products p
set slug = public.price_slugify(b.slug || '-' || p.model_number)
from public.brands b
where b.id = p.brand_id and b.slug in ('stonewater-audio', 'kasper')
  and p.price_group_id is not null
  and p.slug is distinct from public.price_slugify(b.slug || '-' || p.model_number);

-- D1000 is not in the Excel sheet. Only deleted while it has no SKUs.
delete from public.products p
using public.brands b
where b.id = p.brand_id and b.slug = 'stonewater-audio' and p.model_number = 'D1000'
  and not exists (select 1 from public.variants v where v.product_id = p.id);

commit;
